func (*R342RestrictRemoteSAMDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R34.2 - RestrictRemoteSAM non configuré",
		Description: "ANSSI R34.2 (sub-reco) - SAM\\RestrictRemoteSam must be set to a SDDL allowing only admins. Without it, any domain user can enumerate local accounts via SAMR (Mimikatz / netsesh).",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/sub_recos.go",
	}
}

// Doc returns catalog metadata for R361LAPSExpiryDetector.
func (*R361LAPSExpiryDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "LAPS password expiry beyond product benchmark (30 days)",
		Description: "ANSSI PA-099 R30 requires an automatic local-admin-password rotation solution (LAPS or equivalent) but specifies no rotation-interval number. %d computer(s) currently have a LAPS expiry timestamp more than %d days in the future - beyond the legacy LAPS default and etc-collector's product benchmark for 'rotation interval too long'. Reduce the LAPS GPO PasswordAgeDays to %d (or lower).",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/sub_recos.go",
	}
}

// Doc returns catalog metadata for R36CARisksDetector.
func (*R36CARisksDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R36 - Certificate authority risks affecting Tier 0",
		Description: ". ANSSI R36 requires addressing CA-level risks before they enable attackers to mint Tier 0 credentials. Renew expiring/SHA-1 CA certs, lock down CA ACLs, restrict risky templates (approval, remove ESC patterns).",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R37AppLockerHeuristicDetector.
func (*R37AppLockerHeuristicDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "AppLocker / WDAC absent (heuristique GPO)",
		Description: "ANSSI PA-099 R11 (p.28) recommends applying system/software hardening measures that contribute to Tier isolation, which includes application allow-listing (AppLocker, WDAC, or equivalent). HEURISTIC ONLY: no GPO display name mentions AppLocker / WDAC / Code Integrity / SRP. The actual policy quality (XML rules under SYSVOL) is not inspected by this detector, and a hinting or non-hinting GPO name proves nothing about whether allow-listing is actually enforced.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r34_to_r39_hardening.go",
	}
}

// Doc returns catalog metadata for R37WeakCertTemplatesDetector.
func (*R37WeakCertTemplatesDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R37 - Weak or abusable certificate templates",
		Description: "%d certificate template(s) usable for AD authentication carry weaknesses that can produce attacker-controlled or over-permissive Tier 0 certs (ESC1, AnyPurpose, weak ACL): %s. ANSSI R37 forbids weak/vulnerable Tier 0 certs - restrict EnrolleeSuppliesSubject, require manager approval for Smart Card Logon templates, and remove the AnyPurpose EKU from templates issued to privileged identities.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r37_weak_certs.go",
	}
}

// Doc returns catalog metadata for R38AdvancedAuditDetector.
func (*R38AdvancedAuditDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Advanced Audit Policy incomplet",
		Description: "ANSSI PA-099 R13 (p.30) requires logging and centralizing security-relevant events, in particular anything that could signal an attempt to bypass Tier segregation or to move laterally. Checked via either the modern Advanced Audit Policy Configuration (audit.csv, present when any GPO's AdvancedAudit map is populated) or, as a fallback, the legacy [Event Audit] section requiring success+failure (level 3, not just level 1) on Account Logon / Account Mgmt / DS Access / Logon Events / Object Access. An audit policy applied purely through local security policy on each DC (outside any GPO) is not visible to either source.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r34_to_r39_hardening.go",
	}
}

// Doc returns catalog metadata for R39SecurityLogSizeDetector.
func (*R39SecurityLogSizeDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Security event log < 1 GB on Domain Controllers",
		Description: "ANSSI PA-099 R13 (p.30) requires logging and centralizing security-relevant events, which a log that rolls over in minutes under heavy auth load defeats. No GPO both sets the Security event log to at least 1 GB (etc-collector product benchmark; Windows default is 20 MB) AND is linked (enabled, not disabled) to the Domain Controllers OU or the domain root - the only scopes that reliably reach Domain Controllers.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r34_to_r39_hardening.go",
	}
}

// Doc returns catalog metadata for R3StrongAuthDetector.
func (*R3StrongAuthDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Strong Authentication Not Enforced for Privileged Accounts",
		Description: "Privileged accounts should require strong authentication (smartcard, Windows Hello for Business, or a FIDO2 security key) instead of a password alone. Recognized as a best practice by ANSSI's hygiene guide (measure M13, \"privilégier lorsque cela est possible une authentification forte\"); not a PA-099 requirement.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r3-strong-auth.go",
	}
}

// Doc returns catalog metadata for R40NoPSOTier0Detector.
func (*R40NoPSOTier0Detector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R40 - Tier 0 admin groups are not covered by a fine-grained password policy",
		Description: "ANSSI R40 requires applying stricter password policies (FGPP/PSO) to Tier 0 accounts than to regular users. None of the %d configured PSO(s) targets any of the %d Tier 0 group(s) or %d Tier 0 user(s) (recursive expansion + AdminSDHolder). Create one PSO with stricter length/age/lockout settings and apply it to Domain Admins, Enterprise Admins, Schema Admins and the other privileged groups (or directly to user accounts).",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r15_r19_r40_tier0.go",
	}
}

// Doc returns catalog metadata for R42TrustPasswordOldDetector.
func (*R42TrustPasswordOldDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R42 - Trust password not recently rotated",
		Description: "ANSSI R42 (p.55) requires regularly controlling (quarterly, per R42's own suggested cadence) that no trust account password escapes Windows' automatic 30-day rotation. %d trust(s) have a pwdLastSet older than %d days. A value past 90 days means at least one full ANSSI-recommended quarterly review cycle has gone by without the trust password rotating - broken automatic rotation, turning the trust account into a long-lived static credential.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r42_r43_password_rotation.go",
	}
}

// Doc returns catalog metadata for R43DCPasswordOldDetector.
func (*R43DCPasswordOldDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R43 - Domain Controller machine password not rotated",
		Description: "ANSSI R43 requires monitoring renewal of sensitive computer account passwords. %d/%d Domain Controller(s) have a machine password older than %d days. Most often this indicates a misconfigured GPO disabling automatic machine account password change (Netlogon\\DisablePasswordChange=1) or a stale clone DC.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r42_r43_password_rotation.go",
	}
}

// Doc returns catalog metadata for R49R50MgmtCategorizationDetector.
func (*R49R50MgmtCategorizationDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R49+R50 - Management agents not categorized into a dedicated Tier OU",
		Description: "%d computer(s) match centralized-management heuristics (SCCM/WSUS/Defender/Intune/...) but live outside any Tier 0/Tier 1/admin OU. ANSSI R49 (p.62-63) + R50 (p.64) require categorization of management infrastructure: place these systems into a dedicated OU and apply the corresponding tier-segregated GPOs/ACLs. HEURISTIC ONLY, on both signals: matching is by hostname/OS/description keyword and by an OU-name marker, an architectural control that isn't literally encoded anywhere in AD. A real management server with none of the mgmtAgentMarkers substrings in its name/description (custom or renamed product) is a false negative - R49/R50 do not fire for it even if it's genuinely miscategorized. Conversely, a correctly-tiered management server whose OU simply doesn't contain a recognized tier-name marker (e.g. a customer's own naming convention) is a false positive - flagged here despite being properly segregated in practice.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R4LoggingDetector.
func (*R4LoggingDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI PA-099 R13 - Insufficient Security Event Logging",
		Description: "Logging configuration does not meet ANSSI PA-099 R13 (\"Journaliser et centraliser les évènements de sécurité\", p.30). R13 itself defers the exact event categories to two companion ANSSI logging guides; the categories checked here (Account Logon, Account Management, Logon/Logoff, Policy Change, Privilege Use) are this product's operationalization of R13's general requirement, not a verbatim R13 list.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r4-logging.go",
	}
}

// Doc returns catalog metadata for R59Tier0OUPoliciesDetector.
func (*R59Tier0OUPoliciesDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R59 (partial) - Weak-ACL GPO linked to a Tier 0 OU",
		Description: "%d GPO link(s) attach a GPO with a weak ACL (writable by non-admins) to a Tier 0 OU: %s. ANSSI R59 requires GPOs linked to the Tier 0 OU to be dedicated and admin-only-modifiable - this is the ONE of R59's three components this check covers. It does NOT verify that the Tier 0 OU blocks GPO inheritance, nor that the Default Domain Policy is relinked to it at the lowest priority (both required by R59, neither observable with currently-collected data). A low-trust user with write access on a linked GPO can pivot to Tier 0 by editing the policy.",
		Severity:    types.SeverityCritical,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R5SegregationDetector.
func (*R5SegregationDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI PA-099 R7/R8 - Tier Segregation Non-Compliant",
		Description: "Privilege segregation does not meet ANSSI PA-099 R8 (\"Cloisonner l'administration de chaque Tier\", p.24-25): accounts, admin workstations and methods must not create attack paths from one Tier to a less sensitive one. A single account holding multiple privileged-Tier group memberships is such a path.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r5-segregation.go",
	}
}

// Doc returns catalog metadata for R6InactiveAccountsDetector.
func (*R6InactiveAccountsDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Comptes inactifs non désactivés (90j, product benchmark)",
		Description: "Accounts inactive for more than 90 days should be disabled to reduce the attack surface. 90 days is etc-collector's product benchmark; no ANSSI PA-099 recommendation prescribes this figure.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r6_to_r15_lifecycle.go",
	}
}

// Doc returns catalog metadata for R73NTLMOutboundTier0Detector.
func (*R73NTLMOutboundTier0Detector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R73 - Outbound NTLM traffic not blocked on Tier 0",
		Description: "ANSSI R73 requires Tier 0 systems (DCs, admin servers) to refuse outgoing NTLM authentication. No GPO sets Lsa\\MSV1_0\\RestrictSendingNTLMTraffic to 2 (Deny all) AND is actually linked (enabled) to Tier 0 - either the domain root, a Tier 0 OU, or the Domain Controllers container. A GPO with the right value that's linked elsewhere does not satisfy R73. Without it, a compromised low-trust server can coerce a DC to NTLM-authenticate to it (PetitPotam, PrinterBug) and have its hash relayed.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/r73_r74_ntlm_outbound.go",
	}
}

// Doc returns catalog metadata for R74NTLMOutboundDomainDetector.
func (*R74NTLMOutboundDomainDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R74+ - Outbound NTLM traffic not blocked domain-wide",
		Description: "ANSSI R74+ (renforcement) extends R73 to ALL systems that can support it. No GPO with Lsa\\MSV1_0\\RestrictSendingNTLMTraffic=2 (Deny) is linked at the domain root, so most member servers/workstations still emit NTLM, sustaining the relay/coercion attack surface. Link the deny-NTLM-outbound GPO at the domain root (with appropriate exemption WMI filters for legacy systems).",
		Severity:    types.SeverityLow,
		SourceFile:  "ad/compliance/anssi/r73_r74_ntlm_outbound.go",
	}
}

// Doc returns catalog metadata for R79RDPHardenedDetector.
func (*R79RDPHardenedDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Remote Desktop server-side encryption not hardened",
		Description: "Missing GPO setting(s): . Without forced high encryption + RPC traffic encryption, RDP sessions remain attackable from a network position (downgrade attacks, MITM). This is NOT a measurement of ANSSI R79 (client-side hardening: graphics acceleration, clipboard/smart-card redirection - none of which is currently collected); it is a separate, independent RDP hardening baseline.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R7StaleAccountsNotRemovedDetector.
func (*R7StaleAccountsNotRemovedDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Comptes stales (180j+) non supprimés (product benchmark)",
		Description: "Disabled accounts unused for 180+ days should be deleted to reduce directory bloat and the risk of unnoticed reactivation. 180 days is etc-collector's own product benchmark; no ANSSI PA-099 recommendation prescribes this figure.",
		Severity:    types.SeverityLow,
		SourceFile:  "ad/compliance/anssi/r6_to_r15_lifecycle.go",
	}
}

// Doc returns catalog metadata for R82R83AdminArchitectureDetector.
func (*R82R83AdminArchitectureDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Tier 0 systems do not deny low-trust account logons",
		Description: "Tier 0 systems should refuse logon (network, interactive, RDP) from non-Tier-0 accounts (Domain Users, Authenticated Users, etc.) as a hardening baseline. No GPO sets the corresponding deny privileges with such SIDs: . This is NOT a measurement of ANSSI R82 or R83 (both are about restricting Tier 0's OUTBOUND connections to less-trusted zones, the opposite direction, and the guide's own footnote on R83 says deny-logon GPO settings alone don't satisfy it). Add these SIDs to SeDeny*Right via Group Policy on the Tier 0 OU as a defense-in-depth measure regardless.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R86AdminForestSegregationDetector.
func (*R86AdminForestSegregationDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "ANSSI R86 - Administration forest trust not properly segregated",
		Description: "%d trust(s) target what looks like an administration forest (name contains %s) but lack SID filtering and/or selective authentication. ANSSI R86 (p.116) requires segregation of any administration forest deployed, applying section 3.2.3's outbound-trust hardening (R24, p.40) to the relation between the admin forest and the forests it administers: forest-type trusts must not use SID history (no TREAT_AS_EXTERNAL), external/domain-type trusts must be quarantined (QUARANTINED_DOMAIN), plus selective authentication. CAVEAT: this detector only has a single generic SIDFiltering boolean per trust, not the underlying trust-attribute bitmask - R24 prescribes a DIFFERENT bit per trust type (TREAT_AS_EXTERNAL for Forest trusts vs. QUARANTINED_DOMAIN for External trusts). If SIDFiltering is wired to only one of those bits, a correctly-hardened trust of the other type could be a false positive here; this has never been observed to fire, so the mapping is unverified.",
		Severity:    types.SeverityHigh,
		SourceFile:  "ad/compliance/anssi/phase_d_detectors.go",
	}
}

// Doc returns catalog metadata for R8ServiceAccountsAsUsersDetector.
func (*R8ServiceAccountsAsUsersDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Comptes de service indistincts des comptes nominatifs (heuristic)",
		Description: "Service accounts should be clearly separated from nominative accounts (no mailbox, no HR attributes). Shared hybrids hide privilege and muddy audit trails. This is a general AD hygiene heuristic, not an ANSSI PA-099 requirement.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r6_to_r15_lifecycle.go",
	}
}

// Doc returns catalog metadata for R9ServiceAccountSecretRotationDetector.
func (*R9ServiceAccountSecretRotationDetector) Doc() audit.DetectorDoc {
	return audit.DetectorDoc{
		Title:       "Secrets comptes de service non rotés (>1 an, product benchmark)",
		Description: "Service account credentials should be rotated at least annually (preferably via gMSA). Long-lived static secrets are a persistent credential-theft target. 1 year is etc-collector's own product benchmark; ANSSI PA-099 R33 (p.50-51) recommends least-privilege scoping and Managed Service Accounts for service accounts but does not itself prescribe a rotation interval.",
		Severity:    types.SeverityMedium,
		SourceFile:  "ad/compliance/anssi/r6_to_r15_lifecycle.go",
	}
}
